@0 n="minimum_reduced_contact" d="Smallest occupied-contact distance divided by the sum of covalent radii." B=690
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    best = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0.0 and occ[i] * occ[j] > 0.0:
            value = d / (radii[i] + radii[j])
            if best == 0.0 or value < best:
                best = value
    return best
@end
@1 n="short_contact_compression" d="Smoothly cutoff-weighted covalent-overlap penalty per occupied atom." B=723
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and 0.0 < d < 6.0:
            overlap = max(0.0, (radii[i] + radii[j]) / d - 1.0)
            total += occ[i] * occ[j] * overlap ** 2 * (1.0 - d / 6.0) ** 2
    return total / (2.0 * max(sum(occ), 1e-12))
@end
@2 n="screened_polarity_density" d="Inverse-distance, smoothly cutoff-weighted squared contact polarity per atom." B=698
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and 0.0 < d < 6.0:
            if en[i] is not None and en[j] is not None:
                total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 * (1.0 - d / 6.0) ** 2 / d
    return total / (2.0 * max(sum(occ), 1e-12))
@end
@3 n="contact_atomic_transfer_cost" d="Contact-weighted minimum atomic ionization-minus-affinity transfer cost." B=938
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') or 0.0 for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and 0.0 < d < 6.0:
            if ion[i] is not None and ion[j] is not None:
                w = occ[i] * occ[j] * (1.0 - d / 6.0) ** 2 / d
                cost = min(ion[i] - affinity[j], ion[j] - affinity[i])
                total += w * cost
                weight += w
    return total / max(weight, 1e-12)
@end
@4 n="valence_electron_number_density" d="Composition-averaged H3 valence-electron count divided by atomic volume." B=543
def feature(s):
    if not s:
        return 0.0
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        value = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0.0 and value is not None:
            total += fraction * value
            weight += fraction
    return total / (max(weight, 1e-12) * volume)
@end
@5 n="mean_atomic_hardness" d="Composition-weighted atomic hardness proxy, half ionization energy minus affinity." B=533
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        p = props.get(element) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV') or 0.0
        if fraction is not None and fraction > 0.0 and ion is not None:
            total += fraction * 0.5 * (ion - affinity)
            weight += fraction
    return total / max(weight, 1e-12)
@end
